package com.tencent.weknora.knowledge;

import static org.assertj.core.api.Assertions.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import com.tencent.weknora.security.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.test.web.servlet.request.MockMvcRequestBuilders;

/** Actual Go handler/middleware/SQL/Asynq envelopes; DTO values and SQL effects remain exact. */
class KnowledgeTagGoHttpParityTest {
  @TempDir Path temp;final ObjectMapper json=new ObjectMapper();
  static{try{com.tencent.weknora.retrieval.NativeDatabaseRuntime.initialize();}catch(java.sql.SQLException e){throw new ExceptionInInitializerError(e);}}
  @TestFactory Stream<DynamicTest> actualGoTags()throws Exception{JsonNode cases;try(var in=getClass().getResourceAsStream(resource())){cases=json.readTree(in);}assertThat(cases.size()).isEqualTo(caseCount());var seq=new AtomicInteger();return StreamSupport.stream(cases.spliterator(),false).map(row->DynamicTest.dynamicTest(row.path("name").asText(),()->compare(row,seq.incrementAndGet())));}
  void compare(JsonNode oracle,int no)throws Exception{
    var f=database(no);try{f.jdbc.update("UPDATE knowledge_bases SET creator_id='caller',type='faq',summary_model_id='' WHERE id='kb'");f.jdbc.update("INSERT INTO knowledge_bases(id,tenant_id,creator_id,name,type,embedding_model_id,summary_model_id) VALUES('other-kb',1,'other','Other','faq','embedding','')");f.jdbc.update("INSERT INTO knowledge_tags(id,tenant_id,knowledge_base_id,name,seq_id,color,sort_order,created_at,updated_at) VALUES('tag',1,'kb','Tag',1,'#fff',0,?,?),('other-tag',1,'other-kb','Other',2,'',0,?,?)",seedTime(),seedTime(),seedTime(),seedTime());for(int i=1;i<=2;i++)f.jdbc.update("INSERT INTO chunks(id,tenant_id,knowledge_base_id,knowledge_id,chunk_type,tag_id,seq_id,chunk_index,start_at,end_at,content) VALUES(?,1,'kb','faq-doc','faq','tag',?,0,0,0,'FAQ content')","chunk-"+i,i);
    String name=oracle.path("name").asText();if(name.contains("document-")){f.jdbc.update("UPDATE knowledge_bases SET type='document' WHERE id='kb'");f.jdbc.update("INSERT INTO knowledges(id,tenant_id,knowledge_base_id,type,source,title,parse_status,created_at,updated_at) VALUES('faq-doc',1,'kb','file','manual','Document','completed',?,?)",seedTime(),seedTime());f.jdbc.update("UPDATE chunks SET chunk_type='text'");if(!name.equals("document-empty-ref"))f.jdbc.update("INSERT INTO knowledge_tag_relations(knowledge_id,tag_id) VALUES('faq-doc','tag')");if(name.equals("api-document-audit"))f.jdbc.update("INSERT INTO tenant_api_keys(id,tenant_id,name,key_hash,api_key) VALUES(77,1,'Automation','isolated','isolated')");}if(name.startsWith("shared-")){f.jdbc.update("INSERT INTO organizations(id,name,owner_tenant_id,owner_id) VALUES('org','Org',1,'caller')");if(!name.equals("shared-no-source-list"))f.jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('source','org',1,'admin')");f.jdbc.update("INSERT INTO organization_tenant_members(id,organization_id,tenant_id,role) VALUES('member','org',2,'editor')");f.jdbc.update("INSERT INTO kb_shares(id,knowledge_base_id,organization_id,source_tenant_id,permission,shared_by_user_id) VALUES('share','kb','org',1,?,'caller')",(name.equals("shared-viewer-create")||name.equals("shared-document-viewer-force"))?"viewer":"editor");if(name.equals("shared-revoked-list"))f.jdbc.update("UPDATE kb_shares SET deleted_at=CURRENT_TIMESTAMP WHERE id='share'");}
    var beans=new org.springframework.beans.factory.support.DefaultListableBeanFactory();beans.registerSingleton("jdbc",f.jdbc);beans.registerSingleton("json",json);beans.registerSingleton("tx",f.manager);beans.registerSingleton("authRepository",new AuthRepository(f.jdbc,json));beans.registerSingleton("codec",new KnowledgeBaseCodec(json));var audit=new org.springframework.beans.factory.support.RootBeanDefinition(Class.forName("com.tencent.weknora.security.DeniedRoleAuditService"));audit.setAutowireMode(org.springframework.beans.factory.support.AbstractBeanDefinition.AUTOWIRE_CONSTRUCTOR);beans.registerBeanDefinition("audit",audit);var writes=beans.createBean(KnowledgeBaseWriteAuthorization.class);var reads=new KnowledgeBaseReadAuthorization(f.jdbc,new KnowledgeBaseCodec(json),json,Set.of());var enqueuer=new IndexDeleteEnqueuer(f.tasks,json);var tags=new KnowledgeTagRepository(f.jdbc,json,f.manager,(owner,kb,ids,engines)->enqueuer.enqueue(owner,kb,ids,engines,null),driver()).withDocuments((actor,owner,base,ids)->{if(name.equals("document-queue-error"))throw new IllegalStateException("controlled enqueue failure");new KnowledgeListDeleteEnqueuer(f.tasks,json).withAuditKeys(f.jdbc).enqueue(actor,owner,base,ids,null);});
    var scope=oracle.path("scope");var caps=new HashSet<String>();scope.path("Capabilities").forEach(n->caps.add(n.asText()));var allowed=new HashSet<String>();scope.path("KnowledgeBaseIDs").forEach(n->allowed.add(n.asText()));var caller=new AuthContext(oracle.path("user").asText(),oracle.path("caller_tenant").asLong(1),oracle.path("role").asText(),false,oracle.path("machine").asBoolean()?scope.path("KeyID").asLong():null,scope.path("FullAccess").asBoolean(),caps,allowed);
    var mvc=org.springframework.test.web.servlet.setup.MockMvcBuilders.standaloneSetup(new KnowledgeTagController(tags,writes,reads)).setControllerAdvice(new com.tencent.weknora.api.ApiErrorAdvice()).build();String url="/api/v1/knowledge-bases/kb/tags"+oracle.path("target").asText();var method=org.springframework.http.HttpMethod.valueOf(oracle.path("method").asText());var response=mvc.perform(MockMvcRequestBuilders.request(method,url).requestAttr(CurrentAuth.ATTRIBUTE,caller).contentType("application/json").content(oracle.path("request").asText())).andReturn().getResponse();
    assertThat(response.getStatus()).as("actual Go public status").isEqualTo(oracle.path("status").asInt());assertThat(canonical(json.readTree(response.getContentAsByteArray()))).as("complete actual Go public response").isEqualTo(canonical(oracle.path("body")));
    var rows=f.jdbc.queryForList("SELECT id,seq_id,tenant_id,knowledge_base_id,name,color,sort_order FROM knowledge_tags ORDER BY seq_id");assertThat(canonical(json.valueToTree(rows))).as("complete raw SQL tag state").isEqualTo(canonical(oracle.path("tags")));assertThat(f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE deleted_at IS NULL",Long.class)).isEqualTo(oracle.path("active_chunks").asLong());assertThat(f.jdbc.queryForObject("SELECT COUNT(*) FROM chunks WHERE deleted_at IS NOT NULL",Long.class)).isEqualTo(oracle.path("deleted_chunks").asLong());
    var tasks=json.createArrayNode();for(var task:f.jdbc.queryForList("SELECT type,payload,queue,max_attempts,timeout_millis FROM java_task_jobs ORDER BY created_at,id")){var p=task.get("payload");tasks.add(json.createObjectNode().put("type",task.get("type").toString()).set("payload",p instanceof byte[] b?json.readTree(b):json.readTree(p.toString())));var output=(ObjectNode)tasks.get(tasks.size()-1);output.put("queue",task.get("queue").toString()).put("max_retry",((Number)task.get("max_attempts")).longValue()-1).put("timeout",((Number)task.get("timeout_millis")).longValue());}assertThat(canonical(tasks)).as("actual Go admitted Asynq producer payload/queue/retry/timeout").isEqualTo(canonical(oracle.path("tasks")));
    if(oracle.has("audits")){var actualAudit=json.valueToTree(f.jdbc.queryForList("SELECT tenant_id,actor_user_id,actor_role,action,target_type,target_id,scope_type,scope_id,outcome,CAST(details AS TEXT) AS details FROM audit_logs WHERE action IN ('tag.created','tag.updated','tag.deleted') ORDER BY id"));var expectedAudit=oracle.path("audits").isNull()?json.createArrayNode():oracle.path("audits").deepCopy();for(var row:actualAudit)((ObjectNode)row).set("details",json.readTree(row.path("details").asText()));for(var row:expectedAudit)((ObjectNode)row).set("details",json.readTree(row.path("details").asText()));assertThat(canonical(actualAudit)).as("Go business audit owner/original actor/API identity").isEqualTo(canonical(expectedAudit));}
    }finally{release(f);}
  }
  String resource(){return "/go-tag-public.json";}
  int caseCount(){return 76;}
  DocumentProcessingCompatibilityTest database(int no)throws Exception{var f=new DocumentProcessingCompatibilityTest();f.temp=temp;f.database(no,false);return f;}
  Object seedTime(){return "2026-01-01 00:00:00";}
  String driver(){return "sqlite";}
  void release(DocumentProcessingCompatibilityTest f){}
  JsonNode canonical(JsonNode value){if(value.isNumber())return DecimalNode.valueOf(value.decimalValue().stripTrailingZeros());if(value.isArray()){var out=json.createArrayNode();value.forEach(n->out.add(canonical(n)));return out;}if(value.isObject()){var out=json.createObjectNode();value.fields().forEachRemaining(e->{String key=e.getKey();var node=e.getValue();if(Set.of("id","target_id").contains(key)&&node.isTextual()&&!Set.of("tag","other-tag").contains(node.asText())){assertThat(UUID.fromString(node.asText()).version()).isEqualTo(4);out.put(key,"__new_uuid__");}else if(Set.of("created_at","updated_at").contains(key)&&node.isTextual()&&!node.asText().equals("2026-01-01T00:00:00Z")){assertThat(Instant.parse(node.asText())).isNotNull();out.put(key,"__generated_time__");}else out.set(key,canonical(node));});return out;}return value;}
}
